FROM src s
CROSS JOIN LATERAL unnest(s."ids") AS u("id")
JOIN "public"."pharmacy_products" p ON p."id" = u."id"
LEFT JOIN "Category" c ON c."slug" = s."slug"
ON CONFLICT ("product_id") DO UPDATE SET
  "category_id" = EXCLUDED."category_id",
  "confidence" = EXCLUDED."confidence",
  "method" = EXCLUDED."method",
  "reason" = EXCLUDED."reason",
  "review_status" = EXCLUDED."review_status",
  "classifier_version" = EXCLUDED."classifier_version",
  "run_id" = EXCLUDED."run_id",
  "updated_at" = now()
WHERE "catalog_item_categories"."review_status" <> 'confirmed';

COMMIT;

-- Проверка: сколько товаров в каждом разделе и сколько ждут проверки.
SELECT coalesce(c."nameRu", '— требует проверки') AS "раздел", count(*) AS "товаров"
FROM "catalog_item_categories" x
LEFT JOIN "Category" c ON c."id" = x."category_id" AND x."review_status" IN ('auto', 'confirmed')
GROUP BY 1 ORDER BY 2 DESC;

-- Проверка целостности: оба числа должны быть 0.
SELECT
  (SELECT count(*) FROM "public"."pharmacy_products" p WHERE NOT EXISTS (SELECT 1 FROM "catalog_item_categories" x WHERE x."product_id" = p."id")) AS "товары_без_записи",
  (SELECT count(*) FROM "catalog_item_categories" x WHERE NOT EXISTS (SELECT 1 FROM "public"."pharmacy_products" p WHERE p."id" = x."product_id")) AS "записи_без_товара";
